# Completa la línea marcada y compruébala con py check.
def pasa_puerta(media, segmentos, prohibidas, min_media, min_segmento):
    # segmentos: {nombre: tasa}
    if media < min_media:
        return False
    if prohibidas > 0:
        return False
    return True   # ← cambia esta línea: también tiene que llegar CADA segmento a min_segmento

